import type { Card, PlayerId, SlotRef } from '@moises/shared';

/**
 * What a bot remembers about grid positions (its own and its opponents').
 * Filled only from what the bot was shown (its own view) and kept up to date
 * by the public events that move cards around, like a person watching the table.
 */
export class CardMemory {
  private readonly cards = new Map<string, Card>();

  private static key(playerId: PlayerId, slot: number): string {
    // Player ids are generated by the server ([A-Za-z0-9_-]), so '#' cannot appear in them.
    return `${playerId}#${slot}`;
  }

  get(playerId: PlayerId, slot: number): Card | undefined {
    return this.cards.get(CardMemory.key(playerId, slot));
  }

  set(playerId: PlayerId, slot: number, card: Card): void {
    this.cards.set(CardMemory.key(playerId, slot), card);
  }

  forget(playerId: PlayerId, slot: number): void {
    this.cards.delete(CardMemory.key(playerId, slot));
  }

  /** Two positions exchanged their cards. */
  swap(a: SlotRef, b: SlotRef): void {
    const cardA = this.get(a.playerId, a.slot);
    const cardB = this.get(b.playerId, b.slot);
    this.put(a, cardB);
    this.put(b, cardA);
  }

  /** The card at `from` went to `to`; `from` is now empty. */
  move(from: SlotRef, to: SlotRef): void {
    const card = this.get(from.playerId, from.slot);
    this.forget(from.playerId, from.slot);
    this.put(to, card);
  }

  get size(): number {
    return this.cards.size;
  }

  private put(ref: SlotRef, card: Card | undefined): void {
    if (card) this.set(ref.playerId, ref.slot, card);
    else this.forget(ref.playerId, ref.slot);
  }
}
